/bin/zsh -c "python3 - <<'PY'
import sqlite3
c=sqlite3.connect('file:inputs/db/california_schools.sqlite?mode=ro',uri=True).cursor()
qs={
'A_school_avg':'''SELECT t.sname,f."'`Charter Funding Type` FROM schools s JOIN satscores t ON s.CDSCode=t.cds JOIN frpm f ON s.CDSCode=f.CDSCode WHERE s.District LIKE '"'Riverside%' AND t.AvgScrMath > 400''',
'B_district_having':'''SELECT t.sname,f."'`Charter Funding Type`,s.District,COUNT(*),AVG(t.AvgScrMath) FROM schools s JOIN satscores t ON s.CDSCode=t.cds JOIN frpm f ON s.CDSCode=f.CDSCode WHERE s.District LIKE '"'Riverside%' GROUP BY s.District HAVING AVG(t.AvgScrMath)>400''',
'C_district_join_having':'''SELECT t.sname,f."'`Charter Funding Type`,s.District,COUNT(*),AVG(t.AvgScrMath) FROM schools s JOIN satscores t ON s.CDSCode=t.cds JOIN frpm f ON s.CDSCode=f.CDSCode WHERE s.District LIKE '"'Riverside%' GROUP BY s.District HAVING SUM(t.AvgScrMath)/COUNT(t.sname)>400''',
'D_county':'''SELECT t.sname,f."'`Charter Funding Type`,s.County,s.District,t.AvgScrMath FROM schools s JOIN satscores t ON s.CDSCode=t.cds JOIN frpm f ON s.CDSCode=f.CDSCode WHERE s.County='"'Riverside' AND t.AvgScrMath > 400''',
'E_all_district_avg_compare':'''SELECT t.sname,f."'`Charter Funding Type`,t.AvgScrMath,(SELECT AVG(t2.AvgScrMath) FROM schools s2 JOIN satscores t2 ON s2.CDSCode=t2.cds WHERE s2.District=s.District) da FROM schools s JOIN satscores t ON s.CDSCode=t.cds JOIN frpm f ON s.CDSCode=f.CDSCode WHERE s.District LIKE '"'Riverside%' AND da > 400''',
'F_district_stats':'''SELECT s.District,COUNT(*),COUNT(t.AvgScrMath),AVG(t.AvgScrMath),SUM(t.AvgScrMath) FROM schools s JOIN satscores t ON s.CDSCode=t.cds WHERE s.District LIKE 'Riverside%' GROUP BY s.District''',
}
for k,q in qs.items():
 try:
  rows=c.execute(q).fetchall(); print('\\n',k,len(rows))
  for r in rows[:30]:print(' ',r)
 except Exception as e:print(k,e)
PY"

